import {useParams} from "react-router-dom";
import {useEffect,useState} from "react";
import axios from "axios";

export default function GamePage(){
  const {id}=useParams();
  const [game,setGame]=useState(null);

  useEffect(()=>{
    axios.get(`http://localhost:5000/api/games/${id}`)
      .then(res=>setGame(res.data));
  },[id]);

  if(!game) return <h2>Loading...</h2>;

  return(
    <div className="game-container" style={{ width: '100%', height: '600px' }}>
      <iframe
        id="game-frame"
        title="City Bike Stunt 2"
        src="https://sudoku-online.github.io/a7/city-bike-stunt-2/"
        style={{
          width: '100%',
          height: '100%',
          border: 'none',
        }}
        allowFullScreen
        loading="lazy"
        referrerPolicy="no-referrer-when-downgrade"
        sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-presentation"
      />
    </div>
  );
}
